  {
    "statement": "A study in Scotland found that using a fallowing system resulted in fewer lice on Atlantic salmon in cages.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "In Norway, a replicated, controlled study showed that salmon kept in low intensity artificial light or natural lighting had fewer lice.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "A study in Norway found that the number of lice on salmon increased with the intensity of the artificial light.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "In Ireland, two studies on the use of cleaner wrasse to control sea lice on salmon farms had conflicting results.",
    "citations": []
  },
  {
    "statement": "One controlled study in Ireland discovered that corkwing and goldskinny cleaner wrasse were as effective as chemical treatments for managing lice infestations.",
    "citations": []
  },
  {
    "statement": "A replicated, controlled study in Ireland revealed that rockcook cleaner wrasse were not effective in preventing lice outbreaks.",
    "citations": [
      "738"
    ]
  }
